const tb=(x:number,y:number,w:number,text:string,size=31,color='#fff',h=80)=>T(x,y,w,Math.max(h,size*1.12*text.split('\n').length),text,size,{color,weight:800,lineHeight:1.12})
const table=(x:number,y:number,w:number,widths:number[],rows:string[][],rowHeights:number[],color:string,headerFill:string,bodyFill='#fff',size=14):Element[]=>{
 let yy=y;const out:Element[]=[];rows.forEach((row,ri)=>{let xx=x;row.forEach((text,ci)=>{const ww=w*widths[ci],hh=rowHeights[ri];out.push(B(xx,yy,ww,hh,ci===0&&headerFill===navy?'#dfe6ec':ci===0&&headerFill==='#ff9820'&&ri>0?'#ffe0ba':ri===0?headerFill:bodyFill,{border:`.7px solid ${color}`}));out.push(C(xx+3,yy+2,ww-6,hh-4,text,size,'transparent',{color:ci===0&&headerFill===navy?'#111':ri===0&&['#cbe3f9','#cde5f9','#cae3f9','#d1edf9','#ffe1d2'].includes(headerFill)?'#333':ri===0?'#fff':ci===0&&headerFill==='#ff9820'?'#ec812e':'#333',weight:ri===0?650:400,radius:0,lineHeight:1.3}));xx+=ww});yy+=rowHeights[ri]});return out
}
const ring=(x:number,y:number,size:number,pct:number,color:string,label:string,fill='#fff'):Element[]=>{
 const cx=x+size/2,cy=y+size/2,rad=size*.42;const pts=Array.from({length:65},(_,i)=>{const a=(-90+i*360*pct/100/64)*Math.PI/180;return[cx+rad*Math.cos(a),cy+rad*Math.sin(a)]});return[B(x,y,size,size,fill,{radius:'50%',border:`${size*.11}px solid #ddd`}),P(pts,color,size*.11),C(x+size*.15,y+size*.25,size*.7,size*.5,label,size*.24,'transparent',{color,weight:800})]
}
const gauge=(x:number,y:number,size:number,pct:number,color:string):Element[]=>{
 const cx=x+size/2,cy=y+size/2,rad=size*.42;const arc=(span:number)=>Array.from({length:41},(_,i)=>{const a=(180+i*span/40)*Math.PI/180;return[cx+rad*Math.cos(a),cy+rad*Math.sin(a)]});return[P(arc(180),'#fff',size*.11),P(arc(180*pct/100),color,size*.11)]
}
const openRing=(x:number,y:number,size:number,pct:number,color:string,label:string):Element[]=>{
 const cx=x+size/2,cy=y+size/2,rad=size*.42
 const arc=(span:number)=>Array.from({length:65},(_,i)=>{const a=(135+i*span/64)*Math.PI/180;return[cx+rad*Math.cos(a),cy+rad*Math.sin(a)]})
 return[P(arc(270),'#ddd',size*.11),P(arc(270*pct/100),color,size*.11),C(x+size*.15,y+size*.25,size*.7,size*.5,label,size*.24,'transparent',{color,weight:800})]
}
const manual=(key:string,els:Element[])=>{const p=patches[key];p.removeText=[r(0,0,1280,909)];p.elements=[...(p.elements??[]).filter(e=>e.kind!=='text'),...els]}
